{"id": "el-tatio-geysers", "n": "El Tatio Geysers", "c": "Chile", "cont": "South America", "k": "nature", "lat": -22.331389, "lng": -68.010278, "why": "Dawn field of steaming geysers high in the Andes", "desc": "El Tatio is a geothermal field with many geysers located in the Andes Mountains of northern Chile at 4,320 metres (14,170 ft) above mean sea level. It is the third-largest geyser field in the world and the largest in the Southern Hemisphere.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/G%C3%A9iseres_del_Tatio%2C_Atacama%2C_Chile%2C_2016-02-01%2C_DD_01-02_HDR.JPG/500px-G%C3%A9iseres_del_Tatio%2C_Atacama%2C_Chile%2C_2016-02-01%2C_DD_01-02_HDR.JPG", "wiki": "https://en.wikipedia.org/wiki/El_Tatio"},
{"id": "marble-caves", "n": "Marble Caves", "c": "Chile", "cont": "South America", "k": "nature", "lat": 54.258428, "lng": -7.814314, "why": "Swirled marble caverns glowing above impossibly blue water", "desc": "The Marble Arch Caves are a series of natural limestone caves located near the village of Florencecourt in County Fermanagh, Northern Ireland.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Marble_Arch_Caves_-_gour_pools_and_flowstone.jpg/500px-Marble_Arch_Caves_-_gour_pools_and_flowstone.jpg", "wiki": "https://en.wikipedia.org/wiki/Marble_Arch_Caves"},
{"id": "paranal-observatory", "n": "Paranal Observatory", "c": "Chile", "cont": "South America", "k": "geek", "lat": -24.627222, "lng": -70.404167, "why": "Bond villain's lair in Quantum of Solace, atop the Atacama", "desc": "Paranal Observatory is an astronomical observatory operated by the European Southern Observatory (ESO). It is located in the Atacama Desert of Northern Chile on Cerro Paranal at 2,635 m (8,645 ft) altitude, 120 km (70 mi) south of Antofagasta.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Paranal_top.jpg/500px-Paranal_top.jpg", "wiki": "https://en.wikipedia.org/wiki/Paranal_Observatory"},
{"id": "salar-de-atacama", "n": "Salar de Atacama", "c": "Chile", "cont": "South America", "k": "nature", "lat": -23.5, "lng": -68.25, "why": "Vast salt flat with flamingo lagoons ringed by volcanoes", "desc": "Salar de Atacama, located 55 km (34 mi) south of San Pedro de Atacama, is the largest salt flat in Chile. It is surrounded by mountains and lacks drainage outlets.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Salar_de_Atacama.jpg/500px-Salar_de_Atacama.jpg", "wiki": "https://en.wikipedia.org/wiki/Salar_de_Atacama"},
{"id": "san-cristobal-hill", "n": "San Cristobal Hill", "c": "Chile", "cont": "South America", "k": "vista", "lat": -33.420344, "lng": -70.629896, "why": "Santiago spread out below the snow-capped Andes", "desc": "San Cristóbal Hill is a hill in northern Santiago, Chile. It rises 880 m AMSL and about 300 m above the rest of Santiago; the peak is the third highest point in the city, after Cerro Manquehue and Cerro Renca.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/San_Crist%C3%B3bal_altura.jpg/500px-San_Crist%C3%B3bal_altura.jpg", "wiki": "https://en.wikipedia.org/wiki/San_Crist%C3%B3bal_Hill"},
{"id": "santa-lucia-hill", "n": "Santa Lucia Hill", "c": "Chile", "cont": "South America", "k": "vista", "lat": -33.44, "lng": -70.644, "why": "Terraced garden hill with the classic Santiago overlook", "desc": "Santa Lucía Hill, also known in Mapuche as Huelén Hill, is a hill in the centre of Santiago, Chile. It is situated between Alameda del Libertador Bernardo O'Higgins in the south, Santa Lucía Street in the west and Victoria Subercaseaux on the east.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Cerro_Santa_Luc%C3%ADa_desde_el_Cerro_San_Crist%C3%B3bal.jpg/500px-Cerro_Santa_Luc%C3%ADa_desde_el_Cerro_San_Crist%C3%B3bal.jpg", "wiki": "https://en.wikipedia.org/wiki/Santa_Luc%C3%ADa_Hill"},
{"id": "torres-del-paine", "n": "Torres del Paine", "c": "Chile", "cont": "South America", "k": "nature", "lat": -51, "lng": -73, "why": "Granite towers, glaciers and guanacos, Patagonia's greatest hits", "desc": "Torres del Paine National Park is a national park encompassing mountains, glaciers, lakes, and rivers in southern Chilean Patagonia. The Cordillera del Paine group of mountains is the park's centerpiece.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Torres_del_Paine_y_cuernos_del_Paine%2C_montaje.jpg/500px-Torres_del_Paine_y_cuernos_del_Paine%2C_montaje.jpg", "wiki": "https://en.wikipedia.org/wiki/Torres_del_Paine_National_Park"},
{"id": "valle-de-la-luna", "n": "Valle de la Luna", "c": "Chile", "cont": "South America", "k": "nature", "lat": -22.9112, "lng": -68.32303, "why": "Wind-carved lunar dunes glowing at Atacama sunset", "desc": "Valle de la Luna is located 13 kilometres (8 mi) west of San Pedro de Atacama, in the north of Chile in the Cordillera de la Sal, in the Atacama Desert.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Valle_della_Luna_01.jpg/500px-Valle_della_Luna_01.jpg", "wiki": "https://en.wikipedia.org/wiki/Valle_de_la_Luna_(Chile)"},
{"id": "valparaiso", "n": "Valparaiso", "c": "Chile", "cont": "South America", "k": "geek", "lat": -33.046111, "lng": -71.619722, "why": "Whole hillside city is a riot of street art and funiculars", "desc": "Valparaíso is a major city, commune, seaport, and naval base facility in the Valparaíso Region of Chile. Valparaíso was originally named after Valparaíso de Arriba, in Castile-La Mancha, Spain. With a population of 284,938, it is the 10th-largest commune in Chile.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Historic_Quarter_of_the_Seaport_City_of_Valpara%C3%ADso_04.jpg/500px-Historic_Quarter_of_the_Seaport_City_of_Valpara%C3%ADso_04.jpg", "wiki": "https://en.wikipedia.org/wiki/Valpara%C3%ADso"},
{"id": "villarrica-volcano", "n": "Villarrica Volcano", "c": "Chile", "cont": "South America", "k": "nature", "lat": -39.420833, "lng": -71.939167, "why": "Smoking lava-lake volcano above a lakeside adventure town", "desc": "Villarrica is one of Chile's most active volcanoes, rising above the lake and town of the same name, 750 km (470 mi) south of Santiago. It is also known as Rucapillán, a Mapuche word meaning \"great spirit's house\" or \" the demon's house\".", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Puc%C3%B3n%2C_2019_%2801%29%2C_Volc%C3%A1n_Villarrica.jpg/500px-Puc%C3%B3n%2C_2019_%2801%29%2C_Volc%C3%A1n_Villarrica.jpg", "wiki": "https://en.wikipedia.org/wiki/Villarrica_(volcano)"},
{"id": "barranquilla-s-carnival", "n": "Barranquilla's Carnival", "c": "Colombia", "cont": "South America", "k": "geek", "lat": 10.963889, "lng": -74.796389, "why": "UNESCO Caribbean carnival, wilder and more folkloric than Rio", "desc": "The Barranquilla Carnival is one of Colombia's most important folkloric celebrations, and one of the biggest carnivals in the world. The carnival has traditions that date back to the 19th century.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Carnaval_de_barranquilla.png/500px-Carnaval_de_barranquilla.png", "wiki": "https://en.wikipedia.org/wiki/Barranquilla_Carnival"},
{"id": "cano-cristales", "n": "Cano Cristales", "c": "Colombia", "cont": "South America", "k": "nature", "lat": 2.264167, "lng": -73.794444, "why": "The 'river of five colors' blooming liquid-rainbow red", "desc": "The Caño Cristales is a river located in the Serranía de la Macarena, an isolated mountain range in Meta Department, Colombia. It is a tributary of the Guayabero River, itself a part of the Orinoco basin. Caño Cristales was found in 1969 by a group of cattle farmers.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Ca%C3%B1o_Cristales_01.jpg/500px-Ca%C3%B1o_Cristales_01.jpg", "wiki": "https://en.wikipedia.org/wiki/Ca%C3%B1o_Cristales"},
{"id": "cartagena", "n": "Cartagena", "c": "Colombia", "cont": "South America", "k": "temple", "lat": 10.4, "lng": -75.5, "why": "Walled Caribbean old town of bougainvillea and colonial color", "desc": "Cartagena, known since the imperial era as Cartagena de Indias, is a city and one of the major ports on the northern coast of Colombia in the Caribbean Coast Region, along the Caribbean Sea.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Museo_Naval_del_Caribe.JPG/500px-Museo_Naval_del_Caribe.JPG", "wiki": "https://en.wikipedia.org/wiki/Cartagena%2C_Colombia"},
{"id": "ciudad-perdida", "n": "Ciudad Perdida", "c": "Colombia", "cont": "South America", "k": "temple", "lat": 11.037997, "lng": -73.925192, "why": "Jungle 'Lost City' reached only by a multi-day trek", "desc": "Ciudad Perdida is the archaeological site of an ancient city in the Sierra Nevada de Santa Marta of Colombia, within the jurisdiction of the municipality of Santa Marta. This city is believed to have been founded about 800 AD.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/CIUDAD_PERDIDA_2.jpg/500px-CIUDAD_PERDIDA_2.jpg", "wiki": "https://en.wikipedia.org/wiki/Ciudad_Perdida"},
{"id": "el-penon-de-guatape", "n": "El Penon de Guatape", "c": "Colombia", "cont": "South America", "k": "vista", "lat": 6.219452, "lng": -75.179155, "why": "740 stairs up a monolith over a maze of turquoise lakes", "desc": "The Rock of Guatapé is a landmark inselberg in Colombia. It is located in the town and municipality of Guatapé, Antioquia.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/El_Pe%C3%B1ol_de_Guatap%C3%A9_%28The_Rock_of_Guatape%29_2017-04-10.jpg/500px-El_Pe%C3%B1ol_de_Guatap%C3%A9_%28The_Rock_of_Guatape%29_2017-04-10.jpg", "wiki": "https://en.wikipedia.org/wiki/El_Pe%C3%B1%C3%B3n_de_Guatap%C3%A9"},
{"id": "gold-museum", "n": "Gold Museum", "c": "Colombia", "cont": "South America", "k": "museum", "lat": 4.601919, "lng": -74.072, "why": "Dazzling hoard of pre-Columbian gold and the El Dorado raft", "desc": "The Museum of Gold is an archaeology museum located in Bogotá, Colombia. It is one of the most visited tourist highlights in the country. The museum receives around 500,000 tourists per year.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/BOG_04_2012_Museo_de_Oro_1273.JPG/500px-BOG_04_2012_Museo_de_Oro_1273.JPG", "wiki": "https://en.wikipedia.org/wiki/Gold_Museum%2C_Bogot%C3%A1"},
{"id": "la-candelaria", "n": "La Candelaria", "c": "Colombia", "cont": "South America", "k": "geek", "lat": 4.591722, "lng": -74.07413, "why": "Bogota's old quarter packed with political and fantastical graffiti", "desc": "La Candelaria is the 17th locality of Bogotá, Colombia. It is a historic neighborhood located in the city's downtown area, similar to the Old City in other cities. The architecture in La Candelaria features Spanish Colonial, Baroque, and art deco styles.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/BOG_La_Candelaria_alta.JPG/500px-BOG_La_Candelaria_alta.JPG", "wiki": "https://en.wikipedia.org/wiki/La_Candelaria%2C_Bogot%C3%A1"},
{"id": "monserrate", "n": "Monserrate", "c": "Colombia", "cont": "South America", "k": "vista", "lat": 4.605833, "lng": -74.056389, "why": "3,150m shrine looking down the length of sprawling Bogota", "desc": "Monserrate is a mountain over 3,000 metres high that overlooks the city center of Bogotá, the capital city of Colombia. It rises to 3,152 meters (10,341 ft) above the sea level, where there is a church with a shrine, devoted to El Señor Caído.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8f/2017_Bogot%C3%A1_Bas%C3%ADlica_del_Se%C3%B1or_Ca%C3%ADdo_de_Monserrate.jpg/500px-2017_Bogot%C3%A1_Bas%C3%ADlica_del_Se%C3%B1or_Ca%C3%ADdo_de_Monserrate.jpg", "wiki": "https://en.wikipedia.org/wiki/Monserrate"},
{"id": "tayrona-national-park", "n": "Tayrona National Park", "c": "Colombia", "cont": "South America", "k": "nature", "lat": 11.266667, "lng": -74.05, "why": "Jungle tumbling onto boulder-framed Caribbean coves", "desc": "The Tayrona National Natural Park is a protected area in the Colombian northern Caribbean region and within the jurisdiction of the city of Santa Marta, 34 kilometres (21 mi) from the city centre.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Arrecifes.jpg/500px-Arrecifes.jpg", "wiki": "https://en.wikipedia.org/wiki/Tayrona_National_Natural_Park"},
{"id": "banos-de-agua-santa", "n": "Banos de Agua Santa", "c": "Ecuador", "cont": "South America", "k": "onsen", "lat": -1.396389, "lng": -78.424722, "why": "Hot-spring town below a volcano, gateway to waterfall row", "desc": "Baños de Agua Santa, commonly referred to as Baños, is a city in eastern Tungurahua Province of Ecuador. Baños is the second most populous city in Tungurahua, after the capital Ambato, and is a major tourist center.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Ba%C3%B1os%2C_Ecuador.JPG/500px-Ba%C3%B1os%2C_Ecuador.JPG", "wiki": "https://en.wikipedia.org/wiki/Ba%C3%B1os_de_Agua_Santa"},
{"id": "cotopaxi", "n": "Cotopaxi", "c": "Ecuador", "cont": "South America", "k": "nature", "lat": -0.680556, "lng": -78.437778, "why": "Snow-capped near-perfect volcanic cone on the equator", "desc": "Cotopaxi is an active stratovolcano in the Andes Mountains, located in Cotopaxi National Park in Cotopaxi Province, about 50 km (31.1 mi) south of Quito, and 31 km (19 mi) northeast of the city of Latacunga, Ecuador.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Cotopaxi_volcano_2008-06-27T1322.jpg/500px-Cotopaxi_volcano_2008-06-27T1322.jpg", "wiki": "https://en.wikipedia.org/wiki/Cotopaxi"},
{"id": "el-panecillo", "n": "El Panecillo", "c": "Ecuador", "cont": "South America", "k": "vista", "lat": -0.228611, "lng": -78.518611, "why": "Winged-Virgin hilltop over Quito's colonial rooftops and volcanoes", "desc": "El Panecillo is a 200-metre-high hill of volcanic-origin, with loess soil, located between southern and central Quito. Its peak is at an elevation of 3,016 metres (9,895 ft) above sea level. The original name used by the aboriginal inhabitants of Quito was Yavirac.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Quito_calle_Garc%C3%ADa_Moreno.jpg/500px-Quito_calle_Garc%C3%ADa_Moreno.jpg", "wiki": "https://en.wikipedia.org/wiki/El_Panecillo"},
{"id": "galapagos-islands", "n": "Galapagos Islands", "c": "Ecuador", "cont": "South America", "k": "nature", "lat": -0.5, "lng": -90.5, "why": "Darwin's living lab of fearless iguanas, tortoises and boobies", "desc": "The Galápagos Islands are an archipelago of volcanic islands in the Eastern Pacific, located around the equator, 485 nautical miles west of the mainland of South America.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Lobo_marino_%28Zalophus_californianus_wollebaeki%29%2C_Punta_Pitt%2C_isla_de_San_Crist%C3%B3bal%2C_islas_Gal%C3%A1pagos%2C_Ecuador%2C_2015-07-24%2C_DD_11.JPG/500px-Lobo_marino_%28Zalophus_californianus_wollebaeki%29%2C_Punta_Pitt%2C_isla_de_San_Crist%C3%B3bal%2C_islas_Gal%C3%A1pagos%2C_Ecuador%2C_2015-07-24%2C_DD_11.JPG", "wiki": "https://en.wikipedia.org/wiki/Gal%C3%A1pagos_Islands"},
{"id": "historic-center-of-quito", "n": "Historic Center of Quito", "c": "Ecuador", "cont": "South America", "k": "temple", "lat": -0.22, "lng": -78.5125, "why": "Largest, best-preserved colonial old town in the Americas", "desc": "Quito, officially San Francisco de Quito, is the capital and second-largest city of Ecuador, with an estimated population of 2.8 million in its metropolitan area. It is also the capital of the province of Pichincha.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/FACHADA_ASAMBLEA_NACIONAL._QUITO%2C_20_DE_FEBRERO_2020._01.jpg/500px-FACHADA_ASAMBLEA_NACIONAL._QUITO%2C_20_DE_FEBRERO_2020._01.jpg", "wiki": "https://en.wikipedia.org/wiki/Quito"},
{"id": "papallacta", "n": "Papallacta", "c": "Ecuador", "cont": "South America", "k": "onsen", "lat": -0.366944, "lng": -78.132778, "why": "Steamy Andean thermal pools amid paramo and volcanoes", "desc": "Papallacta is a village at an altitude of 3,300 metres in Napo Province, Ecuador. Its population is 635 as of 2022.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Papallacta.JPG/500px-Papallacta.JPG", "wiki": "https://en.wikipedia.org/wiki/Papallacta"},
{"id": "quilotoa", "n": "Quilotoa", "c": "Ecuador", "cont": "South America", "k": "nature", "lat": -0.85, "lng": -78.9, "why": "Emerald crater lake filling a collapsed Andean volcano", "desc": "Quilotoa is a water-filled crater lake and the most western volcano in the Ecuadorian Andes. The 3-kilometre-wide (2 mi) caldera was formed by the collapse of this dacite volcano following a catastrophic VEI-6 eruption about 800 years ago, which produced pyroclastic flo…", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Panorama_quilotoa_crater_lake_ecuador.jpg/500px-Panorama_quilotoa_crater_lake_ecuador.jpg", "wiki": "https://en.wikipedia.org/wiki/Quilotoa"},
{"id": "arequipa", "n": "Arequipa", "c": "Peru", "cont": "South America", "k": "temple", "lat": -16.398889, "lng": -71.536944, "why": "The 'White City' of volcanic-stone baroque beneath El Misti", "desc": "Arequipa is a city in southern Peru and the capital of Arequipa Province and the Department of Arequipa. With a projected population of 1,195,700 in 2025, it is the country's second most populous city after Lima.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Plaza_de_Armas%2C_Arequipa_2006.jpg/500px-Plaza_de_Armas%2C_Arequipa_2006.jpg", "wiki": "https://en.wikipedia.org/wiki/Arequipa"},
{"id": "chan-chan", "n": "Chan Chan", "c": "Peru", "cont": "South America", "k": "temple", "lat": -8.105833, "lng": -79.074444, "why": "Largest adobe city ever built, a vast pre-Inca labyrinth", "desc": "Chan Chan, sometimes called Chimor itself, was the capital city of the Chimor kingdom. It was the largest city of the pre-Columbian era in South America. It is now an archeological site in the department of La Libertad five kilometers (3.1 mi) west of Trujillo, Peru.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Chan_chan_view1.jpg/500px-Chan_chan_view1.jpg", "wiki": "https://en.wikipedia.org/wiki/Chan_Chan"},
{"id": "colca-canyon", "n": "Colca Canyon", "c": "Peru", "cont": "South America", "k": "nature", "lat": -15.597222, "lng": -71.879167, "why": "One of Earth's deepest canyons where condors ride the thermals", "desc": "The Colca Canyon is a canyon of the Colca River in southern Peru, located about 160 kilometres (99 mi) northwest of Arequipa. With a depth of about 3,270 metres (10,730 ft), it is one of the deepest canyons in the world. Its length is about 70 kilometres (43 mi).", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/Colca_Canyon_Puno.jpg/500px-Colca_Canyon_Puno.jpg", "wiki": "https://en.wikipedia.org/wiki/Colca_Canyon"},
{"id": "cusco", "n": "Cusco", "c": "Peru", "cont": "South America", "k": "temple", "lat": -13.5169, "lng": -71.9786, "why": "Inca capital of stonework walls beneath Spanish churches", "desc": "Cusco or Cuzco is a city in southeastern Peru, near the Sacred Valley of the Andes mountain range, and the Huatanay and Urubamba rivers. It is the capital and largest city of the eponymous Cusco Province and Cusco Department.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Vista_Calle_Suecia.jpg/500px-Vista_Calle_Suecia.jpg", "wiki": "https://en.wikipedia.org/wiki/Cusco"},
{"id": "huascaran-national-park", "n": "Huascaran National Park", "c": "Peru", "cont": "South America", "k": "nature", "lat": -9.4, "lng": -77.4, "why": "Turquoise glacial lakes beneath the Cordillera Blanca's icy peaks", "desc": "Huascarán National Park is a Peruvian national park that protects most of the mountain range known as Cordillera Blanca which is part of the central Andes, in the region of Ancash.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Nevado_Huascar%C3%A1n3.jpg/500px-Nevado_Huascar%C3%A1n3.jpg", "wiki": "https://en.wikipedia.org/wiki/Huascar%C3%A1n_National_Park"},
{"id": "huayna-picchu", "n": "Huayna Picchu", "c": "Peru", "cont": "South America", "k": "vista", "lat": -13.1575, "lng": -72.547222, "why": "The dizzy peak looming over the Machu Picchu money-shot", "desc": "Huayna Picchu, Quechua: Wayna Pikchu, is a mountain in Peru around which the Urubamba River bends. It is located in the Cusco Region, Urubamba Province, Machupicchu District. It rises over Machu Picchu, the so-called Lost City of the Incas.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Peru_Machu_Picchu_Sunrise.jpg/500px-Peru_Machu_Picchu_Sunrise.jpg", "wiki": "https://en.wikipedia.org/wiki/Huayna_Picchu"},
{"id": "kuelap", "n": "Kuelap", "c": "Peru", "cont": "South America", "k": "temple", "lat": -6.426295, "lng": -77.927113, "why": "Cloud-forest fortress older and less crowded than Machu Picchu", "desc": "Kuélap or Cuélap is a walled settlement located in the mountains near the towns of María and Tingo, in the southern part of the region of Amazonas, Peru. It was built by the Chachapoyas culture in the 6th century AD on a ridge overlooking the Utcubamba Valley.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Kuelap_-_Ao%C3%BBt_2007_-_05.jpg/500px-Kuelap_-_Ao%C3%BBt_2007_-_05.jpg", "wiki": "https://en.wikipedia.org/wiki/Ku%C3%A9lap"},
{"id": "lake-titicaca", "n": "Lake Titicaca", "c": "Peru", "cont": "South America", "k": "nature", "lat": -15.825, "lng": -69.325, "why": "Highest navigable lake, dotted with floating reed islands", "desc": "Lake Titicaca is a large lake in the Andes mountains on the border of Bolivia and Peru. It is often called the highest navigable lake in the world. It is often listed as a freshwater lake, though its waters are slightly brackish.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Lake_Titicaca_ESA22522896.jpeg/500px-Lake_Titicaca_ESA22522896.jpeg", "wiki": "https://en.wikipedia.org/wiki/Lake_Titicaca"},
{"id": "larco-museum", "n": "Larco Museum", "c": "Peru", "cont": "South America", "k": "museum", "lat": -12.072496, "lng": -77.070862, "why": "Pre-Columbian pottery including a notorious erotic gallery", "desc": "The Larco Museum is a privately owned museum of pre-Columbian art, located in the Pueblo Libre district of Lima, Peru. The museum is housed in an 18th-century vice-royal building.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Lima_museo_larco.jpg/500px-Lima_museo_larco.jpg", "wiki": "https://en.wikipedia.org/wiki/Larco_Museum"},
{"id": "machu-picchu", "n": "Machu Picchu", "c": "Peru", "cont": "South America", "k": "temple", "lat": -13.163333, "lng": -72.545556, "why": "The cloud-wreathed Inca citadel, bucket-list of bucket-lists", "desc": "Machu Picchu is a 15th-century Inca citadel located in the Eastern Cordillera of southern Peru on a mountain ridge at 2,430 meters (7,970 ft).", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Machu_Picchu%2C_2023_%28012%29.jpg/500px-Machu_Picchu%2C_2023_%28012%29.jpg", "wiki": "https://en.wikipedia.org/wiki/Machu_Picchu"},
{"id": "moray", "n": "Moray", "c": "Peru", "cont": "South America", "k": "temple", "lat": -13.329167, "lng": -72.195556, "why": "Concentric Inca terraces like an alien crop-circle amphitheater", "desc": "Moray is an archaeological site in Peru approximately 50 kilometres (31 mi) northwest of Cuzco on a high plateau at about 3,500 metres (11,500 ft) and just west of the village of Maras.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Peru_-_Sacred_Valley_%26_Incan_Ruins_279_-_Moray_%288118174960%29.jpg/500px-Peru_-_Sacred_Valley_%26_Incan_Ruins_279_-_Moray_%288118174960%29.jpg", "wiki": "https://en.wikipedia.org/wiki/Moray_(Inca_ruin)"},
{"id": "nazca-lines", "n": "Nazca Lines", "c": "Peru", "cont": "South America", "k": "temple", "lat": -14.6975, "lng": -75.135, "why": "Giant desert geoglyphs only readable from the sky", "desc": "The Nazca lines are a group of geoglyphs made in the soil of the Nazca Desert in southern Peru. They were created between 500 BC and 500 AD by people making depressions or shallow incisions in the desert floor, removing pebbles and leaving different-colored dirt exposed…", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/L%C3%ADneas_de_Nazca%2C_Nazca%2C_Per%C3%BA%2C_2015-07-29%2C_DD_49.JPG/500px-L%C3%ADneas_de_Nazca%2C_Nazca%2C_Per%C3%BA%2C_2015-07-29%2C_DD_49.JPG", "wiki": "https://en.wikipedia.org/wiki/Nazca_lines"},
{"id": "ollantaytambo", "n": "Ollantaytambo", "c": "Peru", "cont": "South America", "k": "temple", "lat": -13.258056, "lng": -72.263333, "why": "Living Inca town with terraced temple-fortress above", "desc": "Ollantaytambo is a town and an Inca archaeological site in southern Peru some 72 km (45 mi) by road northwest of the city of Cusco. It is located at an altitude of 2,792 m (9,160 ft) above sea level in the district of Ollantaytambo, province of Urubamba, Cusco region.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Ollantaytambo_-_Heiliges_Tal.jpg/500px-Ollantaytambo_-_Heiliges_Tal.jpg", "wiki": "https://en.wikipedia.org/wiki/Ollantaytambo"},
{"id": "sacsayhuaman", "n": "Sacsayhuaman", "c": "Peru", "cont": "South America", "k": "temple", "lat": -13.507778, "lng": -71.982222, "why": "Cyclopean Inca fortress of impossibly fitted mega-stones", "desc": "Sacsayhuamán or Saksaywaman is a citadel on the northern outskirts of the city of Cusco, Peru, the historic capital of the Inca Empire. The site is an important example of Inca architecture and sits at an altitude of 3,701 metres (12,142 ft).", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Sacsayhuam%C3%A1n%2C_Cusco%2C_Per%C3%BA%2C_2015-07-31%2C_DD_27.JPG/500px-Sacsayhuam%C3%A1n%2C_Cusco%2C_Per%C3%BA%2C_2015-07-31%2C_DD_27.JPG", "wiki": "https://en.wikipedia.org/wiki/Sacsayhuam%C3%A1n"},
{"id": "vinicunca-rainbow-mountain", "n": "Vinicunca (Rainbow Mountain)", "c": "Peru", "cont": "South America", "k": "nature", "lat": -13.870227, "lng": -71.302951, "why": "Striped mineral ridge that looks digitally painted, at 5,000m", "desc": "Vinicunca, or Winikunka, also called Montaña de Siete Colores, Montaña de Colores, or Montaña Arcoíris, is a mountain in the Andes of Peru with an altitude of 5,036 metres (16,522 ft) above sea level.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Monta%C3%B1aarcoirisperuabanto.jpg/500px-Monta%C3%B1aarcoirisperuabanto.jpg", "wiki": "https://en.wikipedia.org/wiki/Vinicunca"},
{"id": "casapueblo", "n": "Casapueblo", "c": "Uruguay", "cont": "South America", "k": "geek", "lat": -34.908869, "lng": -55.044906, "why": "Surreal white cliffside 'livable sculpture' by artist Paez Vilaro", "desc": "Casapueblo is a building constructed by the Uruguayan artist Carlos Páez Vilaró. It is located in Punta Ballena, 13 kilometres (8 mi) from Punta del Este, Uruguay.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Casapueblo.JPG/500px-Casapueblo.JPG", "wiki": "https://en.wikipedia.org/wiki/Casapueblo"},
{"id": "colonia-del-sacramento", "n": "Colonia del Sacramento", "c": "Uruguay", "cont": "South America", "k": "temple", "lat": -34.471389, "lng": -57.844167, "why": "Portuguese cobbled river town, oldest in Uruguay", "desc": "Colonia del Sacramento is a city in southwestern Uruguay, by the Río de la Plata, facing Buenos Aires, Argentina. It is one of the oldest towns in Uruguay and the capital of the Colonia Department. As of the 2023 census, it has a population of around 32,174.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Basilica_del_Sanct%C3%ADsimo_Sacramento.jpg/500px-Basilica_del_Sanct%C3%ADsimo_Sacramento.jpg", "wiki": "https://en.wikipedia.org/wiki/Colonia_del_Sacramento"},
{"id": "angel-falls", "n": "Angel Falls", "c": "Venezuela", "cont": "South America", "k": "nature", "lat": 5.9675, "lng": -62.535556, "why": "World's tallest waterfall plunging off a Lost-World tepui", "desc": "Angel Falls  is a waterfall in Venezuela.\nIt is the world's tallest uninterrupted waterfall, with a height of 979 metres (3,212 ft), and a plunge of 807 m (2,648 ft).", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/SaltoAngel1.jpg/500px-SaltoAngel1.jpg", "wiki": "https://en.wikipedia.org/wiki/Angel_Falls"},
{"id": "mount-roraima", "n": "Mount Roraima", "c": "Venezuela", "cont": "South America", "k": "nature", "lat": 5.143333, "lng": -60.7625, "why": "Flat-topped 'Lost World' tepui that inspired Conan Doyle and Up", "desc": "Mount Roraima is the highest of the Pacaraima chain of tepuis or plateaux in South America. It is located at the junction of Brazil, Guyana and Venezuela.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Roraima3_%2879%29.JPG/500px-Roraima3_%2879%29.JPG", "wiki": "https://en.wikipedia.org/wiki/Mount_Roraima"}
